/** Keys used by content/stack.ts on the resume home. */
export const STACK_LOGO: Record<string, string> = {
  "aws": "aws",
  "ci": "github-actions",
  "datadog": "datadog",
  "docker": "docker-icon",
  "kubernetes": "kubernetes",
  "terraform": "terraform-icon",
};

export function LogoMark({
  name,
  className,
  style,
}: {
  /** A key of LOGOS, normally resolved through LOGO_FOR or STACK_LOGO. */
  name: string;
  className?: string;
  style?: CSSProperties;
}) {
  const logo = LOGOS[name];
  if (!logo) return null;
  return (
    <svg
      role="img"
      aria-hidden
      viewBox={`0 0 ${logo.w} ${logo.h}`}
      className={className}
      style={style}
      xmlns="http://www.w3.org/2000/svg"
      dangerouslySetInnerHTML={{ __html: logo.body }}
    />
  );
}

export function hasLogo(name: string | undefined): boolean {
  return Boolean(name && LOGOS[name]);
}
